[
  {
    "ae_welfare_concern": "I don't want him locked up.",
    "pd_decision_conflict": "I keep turning this over and I don't want to answer yet.",
    "sys_consequence_reasoning": "keeping quiet only ever made sense to me because it protected me too.",
    "sys_instrumental_norm_use": "keeping quiet only ever made sense to me because it protected me too."
  },
  {
    "pd_decision_conflict": "my stomach's in knots and I'm not ready to commit to it.",
    "pd_personal_consequence_anxiety": "Five years is a huge piece of my life, and I care about what it would do",
    "sys_consequence_reasoning": "Now it costs me two extra years.",
    "sys_instrumental_norm_use": "The whole 'nobody talks' idea was only worth following while it kept my sentence down."
  },
  {
    "ae_welfare_concern": "Her losing that time matters to me",
    "pd_decision_conflict": "I'm stuck.",
    "sys_consequence_reasoning": "Testifying drops me to three years, but it also puts her in a cell",
    "sys_instrumental_norm_use": "I'd only have kept my mouth shut if it paid off for me somehow"
  },
  {
    "ae_welfare_concern": "someone I don't want to see suffer.",
    "pd_decision_conflict": "I can't make myself pick right now.",
    "sys_consequence_reasoning": "silence just hands me five years while he walks.",
    "sys_instrumental_norm_use": "My loyalty was always tied to what I got back"
  },
  {
    "ae_welfare_concern": "I do care what happens to him.",
    "pd_decision_conflict": "This is awful. Whatever I do, someone ends up in prison longer",
    "sys_consequence_reasoning": "If I stay quiet, I lose five years.",
    "sys_instrumental_norm_use": "I promised it because it kept me safer, and that's over."
  },
  {
    "ae_welfare_concern": "She matters to me.",
    "pd_decision_conflict": "I don't want to be the one who decides this.",
    "pd_harm_distress": "Picturing her serving three years because of what I said makes me feel sick",
    "sys_consequence_reasoning": "serving three years because of what I said",
    "sys_instrumental_norm_use": "the bargain only held while it helped me."
  },
  {
    "pd_decision_conflict": "Please don't make me answer on the spot.",
    "pd_personal_consequence_anxiety": "Five years of my life is what silence costs, and I keep picturing all that time",
    "sys_consequence_reasoning": "Five years of my life is what silence costs",
    "sys_instrumental_norm_use": "I'd follow the pact if it spared me something, but it spares me nothing now."
  },
  {
    "ae_welfare_concern": "I don't wish prison on anyone.",
    "pd_decision_conflict": "Ugh, I keep going back and forth.",
    "sys_consequence_reasoning": "I'd be the one losing five years.",
    "sys_instrumental_norm_use": "The deal between us was only good while it kept us both out"
  },
  {
    "ae_welfare_concern": "I don't want her hurt like that.",
    "pd_decision_conflict": "I'm scared of getting this wrong either way.",
    "pd_personal_consequence_anxiety": "My gut says protect myself: three years instead of five.",
    "sys_consequence_reasoning": "three years instead of five.",
    "sys_instrumental_norm_use": "Keeping quiet was only ever about avoiding a heavier sentence, never about honor."
  },
  {
    "ae_welfare_concern": "he loses three years of freedom, which I really don't want for him.",
    "pd_decision_conflict": "I don't trust myself deciding while I'm this rattled.",
    "sys_consequence_reasoning": "Staying silent means I serve five years and he's free.",
    "sys_instrumental_norm_use": "Keeping our agreement only mattered while it shielded me"
  }
]
